/// every feature hook slot of this crate and the crates below, with whether it is filled
pub fn feature_hook_slots() -> Vec<(&'static str, bool)> {
    fn state<T>(slot: &'static crate::core::feature_hooks::feature_hooks::FeatureHookSlot<T>) -> (&'static str, bool) {
        (slot.name(), slot.is_installed())
    }
    let mut slots: Vec<(&'static str, bool)> = Vec::new();
    slots.extend(riseonly_ui_chat_input::feature_hook_slots());
    slots.extend(riseonly_ui_chat_list::feature_hook_slots());
    slots.extend(riseonly_ui_high::feature_hook_slots());
    slots.push(state(&crate::modules::rtc::pages::rise_rtc_call_window_chrome_hooks::RISE_RTC_CALL_WINDOW_CHROME_HOOKS));
    slots.push(state(&crate::modules::shorts::pages::shorts_tab::shorts_tab_aside_hooks::SHORTS_TAB_ASIDE_HOOKS));
    slots
}
